#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
R1 云端 API 工具(经手机出口,实时签名)
用法:
  python r1_cloud.py usage  [SN]        查 LLM 用量与消费(明文)
  python r1_cloud.py wallet [SN]        查钱包余额
  python r1_cloud.py status [SN]        设备在线状态
  python r1_cloud.py bindlist           绑定设备列表(含设备 key)
  python r1_cloud.py get  <path>        任意 GET (path 不含 host)
  python r1_cloud.py post <path> [json] 任意 POST
默认 SN 为授权测试机。
"""
import json, re, subprocess, sys, time, hashlib, uuid

SECRET = 'XyvkwK45hp5PHfA8'
DEFAULT_SN = 'E39N1000Q72DJE8G'
HOST = 'https://robot-api.unitree.com/'

def get_token():
    out = subprocess.run(['adb','shell','xxd /data/data/com.unitree.b2dog/files/mmkv/mmkv.default'],
                         capture_output=True, text=True).stdout
    hexstr = ''.join(re.findall(r'^[0-9a-f]+: ((?:[0-9a-f]{4} ?)+)', out, re.M)).replace(' ', '')
    return re.search(rb'eyJ[A-Za-z0-9_\-\.]+\.[A-Za-z0-9_\-\.]+\.[A-Za-z0-9_\-\.]+', bytes.fromhex(hexstr)).group().decode()

def call(path, method='GET', body=None):
    token = <访问令牌_01>
    ts = str(int(time.time()*1000)); nonce = uuid.uuid4().hex
    sign = hashlib.md5((SECRET + ts + nonce).encode()).hexdigest()
    parts = [f'curl -s -m 12 -X {method} "{HOST}{path}"',
             '-H "Content-Type: application/json"',
             f'-H "Token: <访问令牌_01>}"',
             f'-H "AppTimestamp: {ts}"', f'-H "AppNonce: {nonce}"', f'-H "AppSign: {sign}"',
             '-H "AppName: B2" -H "DevicePlatform: Android" -H "AppVersion: 2.1.2"',
             '-H "channel: inland" -H "User-Agent: okhttp/4.12.0"']
    if body is not None:
        parts.append(f"-d '{json.dumps(body)}'")
    open(r'C:\zyh\work\宇树固件\real_unitree_r1_1.4.2\tools\c.sh', 'w').write(' '.join(parts))
    subprocess.run(['adb','push',r'C:\zyh\work\宇树固件\real_unitree_r1_1.4.2\tools\c.sh','/data/local/tmp/c.sh'],
                   capture_output=True)
    r = subprocess.run(['adb','shell','sh /data/local/tmp/c.sh'], capture_output=True, timeout=30)
    return r.stdout.decode('utf-8', errors='replace')

def pretty(raw):
    if raw.lstrip().startswith('<'):
        return '<HTML 567页 - 网关拦截>'
    try:
        return json.dumps(json.loads(raw), ensure_ascii=False, indent=2)
    except Exception:
        return raw

def main():
    args = sys.argv[1:]
    if not args:
        print(__doc__); return
    cmd = args[0]
    now = time.localtime()
    if cmd == 'usage':
        sn = args[1] if len(args) > 1 else DEFAULT_SN
        print(pretty(call(f'device/flow/usage?sn={sn}&year={now.tm_year}&month={now.tm_mon}')))
    elif cmd == 'wallet':
        sn = args[1] if len(args) > 1 else DEFAULT_SN
        print(pretty(call(f'device/wallet?sn={sn}', 'POST', {})))
    elif cmd == 'status':
        sn = args[1] if len(args) > 1 else DEFAULT_SN
        print(pretty(call(f'device/online/status?sn={sn}')))
    elif cmd == 'bindlist':
        print(pretty(call('device/bind/list')))
    elif cmd == 'get':
        print(pretty(call(args[1])))
    elif cmd == 'post':
        body = json.loads(args[2]) if len(args) > 2 else {}
        print(pretty(call(args[1], 'POST', body)))
    else:
        print(__doc__)

if __name__ == '__main__':
    main()

